/* ── ПОМЕЩЕНИЯ ── */
D({ rooms: {
  /* Проходная */
  v12_checkpoint: { n: "Проходная", desc: "Ряд железных вертушек, у каждой — табельные часы с прорезью для жетона: компостер щёлкает, пробивая время прихода, хотя смены давно никто не отмечает. У стены — автомат с газировкой, под потолком хрипит репродуктор, а бетон у вертушек вытоптан двумя желобами.",
    obj: { terminal: .5, drinks: .3, desk: .3, locker: .2 }, loot: "paper", sign: ["Предъяви жетон", "Опоздал — к мастеру"], amb: "room_hum", fl: "concrete" },
  v12_tokenboard: { n: "Табельная", desc: "Стена до потолка в латунных жетонах: каждый на своём крючке, под каждым — выбитая фамилия, и на сквозняке они позвякивают, как мелочь в кармане. Одна доска стоит особняком — жетоны третьей смены, все до единого на месте, кроме седьмого, и под ними пыль, которую никто не смахивает.",
    obj: { desk: .6, pc: .5, safe: .3, locker: .3 }, loot: "paper", sign: ["Жетон снял — смену сдал", "Доску третьей смены не трогать"], amb: "room_hum", fl: "wood" },
  v12_masterbooth: { n: "Будка мастера", desc: "Застеклённая будка на стальных ногах над пролётом: стол с журналом нарядов, трубка пневмопочты и микрофон репродуктора на гибкой шее. Стёкла дребезжат в такт прессам. Отсюда видно весь цех — тому, кто видит, — а слышно ещё больше: каждый станок, каждую тележку, каждый шаг.",
    obj: { desk: .8, pc: .7, radio: .4, safe: .4 }, loot: "paper", sign: ["Мастер цеха", "Без наряда не входить"], amb: "room_radio", fl: "wood", rank: 2 },
  /* Литейный двор */
  v12_cupola: { n: "Вагранка", desc: "Высокая шахтная печь ревёт, как водопад в трубе; из летка с треском сыплются искры, и жар бьёт в лицо даже через пролёт. По желобу медленно ползёт шлак и шипит, остывая. Пол из огнеупорного кирпича тёплый, как печной бок, и под ногами чуть подрагивает.",
    obj: { crate: .5, workbench: .3, terminal: .3 }, loot: "parts", sign: ["Не стой под летком", "Шихту — по весу"], amb: "room_generator", fl: "stone" },
  v12_moldfloor: { n: "Формовочный плац", desc: "Широкий плац, засыпанный формовочной землёй: рядами стоят опоки с заготовленными формами, рядом — трамбовки и сита. Песок глотает шаги, и в тишине слышно, как сохнут формы — тонко потрескивают. Пахнет горелой землёй и патокой, на которой замешивали смесь.",
    obj: { workbench: .5, crate: .5 }, loot: "parts", sign: "Опоку не трогать — сохнет", amb: "room_factory", fl: "sand" },
  v12_ladlebay: { n: "Разливочный пролёт", desc: "Под потолком скрипит тележка мостового крана, на тросах покачивается ковш размером с комнату. В песчаных ямах остывают отливки и щёлкают, как остывающая печь, а капли расплава, упав мимо, шипят и прыгают. Каждый шаг по чугунным плитам отдаётся гулко, как по крышке котла.",
    obj: { crate: .4, terminal: .4, workbench: .3 }, loot: "parts", sign: ["Под ковшом не стоять", "Разливка — по гудку"], amb: "room_factory", fl: "v12_castiron" },
  /* Прессовый цех */
  v12_pressline: { n: "Прессовая линия", desc: "Прессы стоят в ряд, как часовые, и бьют по очереди: удар — пауза — удар, и от каждого удара пол подпрыгивает, а в будках звенят стёкла. Лента подачи лязгает, подкладывая под штампы заготовки, которых никто не забирает. Горки готовых деталей растут у каждого пресса и осыпаются со звоном.",
    obj: { workbench: .4, crate: .5, terminal: .3 }, loot: "parts", sign: ["Руки — из-под штампа", "Ритм не сбивать"], amb: "room_factory", fl: "v12_castiron" },
  v12_rhythmpost: { n: "Пост ритма", desc: "Деревянный помост у прессовой линии: на цепях висит обрезок рельса, рядом — молоток с рукоятью, отполированной ладонями. Когда ломалась автоматика подачи, здесь стоял отбойщик и бил в рельс, а подавальщики вдоль линии двигались под его счёт. На стене — стенд с метрономом и задачей на ритм для учеников.",
    obj: { puzzle: .7, desk: .3, radio: .3 }, loot: "tech", sign: ["Отбивать ровно", "Сбился — начни с первого"], amb: "room_hum", fl: "wood" },
  /* Сборочный конвейер */
  v12_conveyor: { n: "Сборочная линия", desc: "Лента шириной с улицу тянется из одного пролёта в другой и не останавливается никогда: по ней едут полусобранные машины — рамы, лапы, корпуса. У постов вдоль ленты трещат гайковёрты и шипит сварка, и каждый пост звучит своим инструментом, как оркестр, который давно играет без дирижёра.",
    obj: { workbench: .6, crate: .4, terminal: .3, implantlab: .2 }, loot: "parts", sign: ["Ленту не останавливать", "Брак — в лоток"], amb: "room_factory", fl: "rubber" },
  v12_handline: { n: "Ручной конвейер", desc: "Старая линия, где привод встал так давно, что его успели забыть: вагонетки с заготовками стоят на рельсах, и их толкали руками, от поста к посту, под счёт. Деревянный пол вытерт ногами в две колеи, а на стенах вырезаны зарубки — по одной на каждую смену, отработанную здесь без мотора.",
    obj: { crate: .5, workbench: .3, radio: .2 }, loot: "parts", sign: "Толкай в лад", amb: "room_hum", fl: "wood" },
  v12_armshop: { n: "Участок рук", desc: "Чистая мастерская, где собирали железные руки для тех, кто оставил свои под прессом: на столах — кисти на шарнирах, пальцы на пружинах, примерочные муфты, и каждая рука щёлкает по-своему, если её согнуть. Отсюда протезы отправляли наверх — когда наверху выросла Лечебница.",
    obj: { implantlab: .5, workbench: .6, locker: .3, pc: .3 }, loot: "tech", sign: ["Руки — по наряду", "Примерка — у мастера"], amb: "room_electric", fl: "tile" },
  v12_blueprint: { n: "Чертёжная", desc: "Длинные столы с наклонными досками и стеллажи рулонов: здесь веками перерисовывали чертежи машин «Глубины» — буровых глубинников, лебёдок, насосов — и каждый новый лист начинали с той же старой подписи в углу: «Утверждаю. Ростовцев». Калька шуршит от любого вздоха, а рейсшины тихо стукаются друг о друга.",
    obj: { desk: .8, pc: .6, safe: .4, locker: .3 }, loot: "paper", sign: ["Чертежи не выносить", "Копия — по журналу"], amb: "room_hum", fl: "wood", rank: 2 },
  /* Кузнечный ряд */
  v12_smithy: { n: "Кузня", desc: "Горны в ряд вдоль закопчённой стены, у каждого — наковальня, и каждая звенит своей нотой: кузнецы подбирали их по тону, как колокола. Меха дышат, угли трещат, на стене висят клещи всех размеров. Каменная брусчатка тёплая и усыпана окалиной, которая похрустывает под подошвой.",
    obj: { workbench: .7, crate: .4 }, loot: "parts", sign: ["Наковальню не будить", "Горн без присмотра не оставлять"], amb: "room_factory", fl: "stone" },
  v12_hammerhall: { n: "Молотовая", desc: "Паровой молот высотой в два этажа: тяжёлый боёк падает с шипением и грохотом, и пол подбрасывает так, что клацают зубы. Рядом — закалочные ванны с маслом и водой: поковка уходит в них с визгом, и пар поднимается к потолку. Между ударами слышно, как капает масло с направляющих.",
    obj: { workbench: .4, crate: .4, terminal: .3 }, loot: "parts", sign: ["Под бойком не стоять", "Удар — по команде"], amb: "room_compressor", fl: "v12_castiron" },
  /* Склады заготовок */
  v12_rackhall: { n: "Стеллажный склад", desc: "Стеллажи уходят под потолок и вдаль, дальше, чем слышно: на полках — болванки, прутки, свёрнутые листы, литьё в промасленной бумаге. По рельсам между рядами ездит штабелёр и гудит, отыскивая полку, которой давно нет в описи. Задень штабель плечом — и он отзовётся долгим низким звоном.",
    obj: { crate: .9, locker: .3, terminal: .3 }, loot: "parts", sign: ["Заготовки — по накладной", "Штабель не раскачивать"], amb: "room_hum", fl: "concrete" },
  v12_expedition: { n: "Экспедиция", desc: "Отгрузочный зал с погрузочной платформой и широкой клетью подъёмника, уходящей вверх; у стены — зарядные колонки для тележек. На ящиках — бирки по трафарету: «Наверх. На стройку». Ящики веками ждут подъёмника, который больше не ходит, а рифлёный лист платформы гремит под каждым шагом.",
    obj: { crate: .8, desk: .4, pc: .3, charger: .3 }, loot: "parts", sign: ["Отгрузка — наверх", "Накладную — к ящику"], amb: "room_compressor", fl: "v12_ribsheet" },
  /* ОТК */
  v12_measure: { n: "Метрологическая", desc: "Самая тихая комната Цехов: слышно, как тикают индикаторы и как дышишь сам. На столах — гири, калибры, концевые меры в бархатных гнёздах, а под стеклянным колпаком — стальная линейка, тёмная от времени, эталон всех мер; говорят, её принёс вниз сам Глотов. У двери — поверочный стенд с задачей для учеников.",
    obj: { desk: .6, pc: .5, safe: .4, puzzle: .3 }, loot: "tech", sign: ["Тишина: идёт поверка", "Эталон руками не трогать"], amb: "room_hum", fl: "tile" },
  v12_testbench: { n: "Испытательный стенд ОТК", desc: "Камера за толстым стеклом, где детали гнули, давили и грели, пока не лопнут, а контролёр по звуку записывал, как они лопаются. Посреди — стенд с пультом обратного отсчёта и створки на гидравлике. Стены в рубцах от осколков, и в углах до сих пор лежат обломки последних проб.",
    obj: { terminal: .5, puzzle: .4, crate: .3 }, loot: "armor", sign: ["Испытание — по вызову", "За стеклом не стоять"], amb: "room_electric", fl: "rubber", trial: true },
  v12_rejects: { n: "Изолятор брака", desc: "Клетки из сетки до потолка, забитые бракованными деталями: кривые валы, треснувшие корпуса, руки, которые не сжимаются. Брак здесь не считают — потому и табельных автоматов нет. С потолка капает, ржавчина шуршит, а в дальнем углу всегда кто-то тихо торгует.",
    obj: { crate: .7, locker: .3, desk: .2 }, loot: "parts", sign: "Брак не считать", amb: "room_drip", fl: "concrete", dark: true },
  /* Инструментальный цех */
  v12_toolcrib: { n: "Инструментальная кладовая", desc: "За решёткой с окошком выдачи — щиты, на которых каждый инструмент висит на своём контуре, обведённом краской: пустой контур значит, что инструмент на руках. Ящики с резцами, ключами, сверлами и опытными штампами. Здесь выдавали лучшее — и только под роспись.",
    obj: { locker: .8, safe: .5, crate: .4 }, loot: "arms", sign: ["Инструмент — под роспись", "Только с допуска"], amb: "room_hum", fl: "wood", rank: 3 },
  v12_grinder: { n: "Заточная", desc: "Шлифовальные круги на станинах визжат так, что «Эхо» само убавляет громкость; искры шуршат о бетон, пахнет горячей сталью и камнем. На стене — таблица углов заточки, на полу — серая пыль, в которой отпечатываются подошвы. Остывая, круги ещё долго поют на одной ноте.",
    obj: { workbench: .7, crate: .3 }, loot: "parts", sign: ["Очки — на глаза", "Круг рукой не тормозить"], amb: "room_electric", fl: "concrete" },
  v12_precision: { n: "Участок точной механики", desc: "Тихий зал с точными станками под чехлами, будто спящими птицами. Станки гудят почти неслышно, микрометры щёлкают трещотками, а мастер у дальнего стола работал когда-то в шерстяных перчатках, чтобы тепло ладоней не меняло размер. На стене — стенд с задачей на допуск, а торцевая шашка на полу пропитана маслом и глушит шаги.",
    obj: { workbench: .8, pc: .4, puzzle: .3 }, loot: "tech", sign: ["Не шуметь: точная работа", "Допуск — сотка"], amb: "room_hum", fl: "wood" },
  v12_trainshop: { n: "Учебный цех", desc: "Мастерская для учеников с верстаками в ряд и стендом пробы посередине: здесь сдавали пробную работу на разряд, и стенд до сих пор отсчитывает время экзамена. На верстаках — тиски, напильники, недопиленные пробные кубики. На стене выцветшие плакаты: «Отмерь по Глотову», «Ритм держи ровно».",
    obj: { workbench: .7, puzzle: .4, desk: .3 }, loot: "parts", sign: ["Проба на разряд", "Ученик — к своему верстаку"], amb: "room_hum", fl: "wood", trial: true },
  /* Пайковый комбинат */
  v12_mushfarm: { n: "Грибные гряды", desc: "Длинные гряды в тёплом компосте под низкими лампами: из земли тянутся бледные шляпки, и полив капает на них с труб ровно, как часы. Пахнет сырой землёй и грибами, под ногами мягко пружинит перепревшая подстилка. Где-то между грядами шуршит и попискивает — крысы тоже любят тепло.",
    obj: { crate: .5, terminal: .2 }, loot: "food", sign: ["Гряды не топтать", "Сбор — по наряду"], amb: "room_drip", fl: "grass" },
  v12_kitchen: { n: "Деевская кухня", desc: "Кухня с котлами в рост человека и каменной плитой во всю стену: в котлах до сих пор что-то булькает, хотя повара давно разошлись. На стене — раскладка, вырезанная по дереву: «По Дееву: каши — черпак, хлеба — ломоть, соли — щепоть». Половники висят рядком и звякают, если задеть один.",
    obj: { coffee: .3, drinks: .3, crate: .4 }, loot: "food", sign: ["По Дееву", "Без халата к котлу не подходить"], amb: "room_bubbles", fl: "tile", safe: true },
  v12_packing: { n: "Фасовочная пайков", desc: "Зал, где пайки заворачивали в промасленную бумагу и укладывали в ящики по двадцать: фасовочный автомат стрекочет, складывая пустые обёртки, раз за разом, с тех пор как кончилась каша. Бумага шуршит, бечёвка поскрипывает, на кафеле — рассыпанная крупа, хрустящая под ногой.",
    obj: { crate: .7, terminal: .3, workbench: .3 }, loot: "food", sign: ["Паёк — по раскладке", "Двадцать в ящик"], amb: "room_factory", fl: "tile" },
  /* Бытовой корпус */
  v12_cloakroom: { n: "Раздевалка смены", desc: "Ряды шкафчиков с номерами и деревянные скамьи, вытертые штанами спецовок; пахнет потом, мылом и машинным маслом. На стене — аптечка Берг с красным крестом и автомат с газировкой. Шкафчик номер один заперт и чист: в нём висит роба, которую ни разу не надевали.",
    obj: { locker: .9, drinks: .3, medst: .2 }, loot: "armor", sign: ["Шкафчик — по номеру", "Роба — в стирку по субботам"], amb: "room_hum", fl: "wood", safe: true },
  v12_redcorner: { n: "Красный уголок", desc: "Комната отдыха смены: на стенах — доска почёта с вытертыми фамилиями и вымпелы передовиков, в углу — радиола, на столе — шахматы с недоигранной партией. Здесь проводили собрания и отдыхали между сменами; ковровая дорожка глушит шаги, а радиола, если её включить, шипит и ловит что-то далёкое.",
    obj: { radio: .6, desk: .4, pc: .3, coffee: .3, capsule: .2 }, loot: "paper", sign: ["Доска почёта", "Тише: идёт собрание"], amb: "room_radio", fl: "carpet", safe: true },
  v12_dorm: { n: "Общежитие вахты", desc: "Двухъярусные койки в три ряда для тех, кто стоял вахты по трое суток и спал прямо в Цехах: у каждой койки — шкафчик, сапоги и будильник, заведённый на пересменку. В углу — капсулы сна, поставленные позже, для самых усталых. Спят здесь чутко: доски скрипят, и сон слушает гудок.",
    obj: { capsule: .5, locker: .6, crate: .3 }, loot: "food", sign: ["Вахта спит", "Будить по гудку"], amb: "room_hum", fl: "wood", safe: true },
  /* Отвал */
  v12_slagdump: { n: "Шлаковый отвал", desc: "Склон из остывающего шлака у самого края Трещины: шлак потрескивает и посвистывает, отдавая тепло, а снизу, из разлома, поднимается ровный гул, от которого ноют зубы. Бадьи, вагонетки, брошенные лопаты. Счётчиков здесь не вешали: отвал не считают, на отвал только переводят.",
    obj: { crate: .4, corpse: .25, locker: .2 }, loot: "parts", sign: "Дальше края не ходить", amb: "room_hum", fl: "sand", dark: true },
  v12_crackshop: { n: "Цех у Трещины", desc: "Цех, наполовину ушедший в разлом: пол обрывается посреди пролёта, и лента конвейера уходит за край и всё бежит — туда, где её никто не ловит. Станки у обрыва стоят накренившись, из-под плит тянет теплом. Сюда давно не заходят ни счётчики, ни Мастер, зато заходят артельщики.",
    obj: { crate: .4, workbench: .3, corpse: .2, radio: .2 }, loot: "tech", sign: ["Цех закрыт", "Кто ушёл — не ждать"], amb: "room_creatures", fl: "stone", dark: true },
  v12_scrapsort: { n: "Сортировка лома", desc: "Двор, где лом разбирали по сортам: магнитная шайба крана висит над кучами, гудит и время от времени роняет то, что держит. Груды гнутого железа звенят, если их задеть, медь — отдельно, чугун — отдельно, брак — в переплав. Пахнет ржавчиной и мокрым железом.",
    obj: { crate: .7, workbench: .4 }, loot: "parts", sign: "Лом — по сортам", amb: "room_factory", fl: "concrete" },
  /* Головной цех */
  v12_firstlathe: { n: "Станок номер один", desc: "Посреди старого цеха — станок, собранный из буровой рамы, лебёдки и насоса, что первые принесли с собой вниз; латунная табличка на станине стёрта пальцами до гладкости. Он до сих пор крутится, медленно и ровно, и шпиндель поёт так низко, что звук слышен грудью. Машины смазывают его каждую смену.",
    obj: { workbench: .6, terminal: .3, crate: .3 }, loot: "parts", sign: ["Станок номер один", "Останавливать — только мастеру"], amb: "room_factory", fl: "stone" },
  v12_mainvalve: { n: "Зал главного вентиля", desc: "Круглый зал, куда снизу сходятся паровые трубы толщиной в обхват; посередине — штурвал главного вентиля выше человеческого роста. Вентиль держит ритм — шипит, лязгает, шипит, — и по этому ритму живут все пролёты. Вокруг — посты вахтенных с затёртыми поручнями и манометры, чьи стрелки дрожат, как живые.",
    obj: { terminal: .5, locker: .3, crate: .3 }, loot: "tech", sign: ["Вахта у вентиля — не меньше трёх", "Со смены не уходить"], amb: "room_pumps", fl: "v12_castiron" },
  v12_tabelhall: { n: "Зал табеля", desc: "Высокий зал, где висят табели всех смен, что работали в Цехах: доски жетонов уходят под самый потолок, к ним ведут передвижные лестницы. Жетоны тихо звенят на сквозняке, и звон этот похож на далёкий дождь. Посреди — стол со счётами, на которых старшие табельщицы сверяли итог смены.",
    obj: { desk: .6, pc: .5, safe: .4, locker: .3 }, loot: "paper", sign: ["Табель — по сменам", "Жетоны не перевешивать"], amb: "room_ring", fl: "stone" },
  /* по всем секторам */
  v12_substation: { n: "Цеховая подстанция", desc: "Бетонная коробка с трансформаторами, которые гудят ровно и басом, как улей размером с цех. На щитах — рубильники с эбонитовыми ручками и стрелки амперметров, по стенам тянутся кабели толщиной в палец. Пахнет озоном и горячим лаком, и от гула чуть покалывает кожу.",
    obj: { terminal: .6, magnetron: .3, crate: .3, charger: .3 }, loot: "tech", sign: ["Не влезай — убьёт", "Рубильник — только дежурному"], amb: "room_transformer", fl: "concrete" }
} });

/* ── ЖУРНАЛЫ ПОМЕЩЕНИЙ ── */
D({ logs: {
  v12_checkpoint: ["Пересменка. Через вертушки прошло: людей — ни одного, тележек — одиннадцать, крыс — без счёта. Компостер исправен. Записано Мастером.", "Опоздание: жетон номер семь пробит позже гудка на целую эпоху. Причина — пришёл сверху. Уважительная ли — решу потом."],
  v12_tokenboard: ["Доска третьей смены: жетонов на месте — все, кроме седьмого. Седьмой унёс с собой тот, кто ушёл первым. Крючок держу пустым.", "На седьмой крючок третьей смены повешен новый жетон. Номер — семь. Владелец — сверху. Табельщица возражала. Возражение записано, жетон висит."],
  v12_masterbooth: ["Журнал нарядов, лист последний. Нарядов выдано — сколько машин в цеху. Нарядов закрыто — столько же. Людей в нарядах — ни одного. Мастер доволен. Мастер не доволен.", "Пневмопочта принесла капсулу снизу. Капсула пустая, но тёплая. Записано: «посторонний предмет в трубе». Записано второй раз за смену."],
  v12_cupola: ["Плавка по заданию: серый чугун на корпуса прессов. Шихта — лом и звонкая руда. Руда в печи поёт. Плавильщики жалуются на песню, плавка идёт.", "Вагранку не гасили со дня пуска. Кто погасит — тому и разжигать. Желающих нет. Пометка рукой: и не будет."],
  v12_moldfloor: ["Опоки на плацу: формы под лапы шагающих прессов — сто двадцать, под шестерни — без счёта. Заливать некому, формы сохнут веками и трескаются.", "Вагранщица Пелагея Деева в свободную смену трамбовала форму на плацу и пела. Мастер сделал замечание. Форма вышла без единой раковины. Замечание снято."],
  v12_ladlebay: ["Разливка по гудку. Гудок дан, ковш наклонён, металл ушёл в форму. Подпись разливщика неразборчива: руки в рукавицах.", "Под ковшом стоял посторонний и слушал, как поёт расплав. Предупреждён. Слушал дальше. Предупреждён повторно."],
  v12_pressline: ["Ритм линии: удар — пауза — удар. Пауза длиннее нормы на долю. Наладчик вызван. Наладчик сам — машина. Пауза осталась.", "Выработка за смену: деталей — гора. Забрано — ничего. Горы у прессов растут, склад полон, а наверху, говорят, давно нужны совсем другие детали."],
  v12_rhythmpost: ["Подача встала третий раз за смену. На пост ритма вызван отбойщик. Отбивал до утра, линия не сбилась. Отбойщику — премия и двое суток тишины.", "Рельс заменён: прежний стёрт молотком до блеска и треснул. Старый повешен в красном уголке и звенит до сих пор, если задеть."],
  v12_conveyor: ["Лента идёт. Собрано за смену: рам — сорок, лап — сто шестьдесят, корпусов — двадцать. Собрано машинами, принято машинами. Куда отправлено — неизвестно.", "На двенадцатом посту сборщик поставил деталь задом наперёд. Машина, собранная с ней, ходит задом наперёд, и ходит хорошо. Записано как рационализация."],
  v12_handline: ["Привод стоит четвёртую смену. Вагонетки толкаем руками, под счёт. Выработка — девяносто от нормы. Мастер: «Девяносто — не сто». Смена: «Мотор — ноль».", "Зарубка на стене за смену без мотора. Зарубок уже больше, чем досок в полу. Привод так и не починили: руки дешевле."],
  v12_armshop: ["Выдано рук по наряду: три левых, две правых. Прессовщику Фролу — правая, вторая за год. Мастер: «Береги». Фрол: «Себе скажи».", "Отправлено наверх, на стройку Лечебницы: ящик рук и ящик ног. Наверху обещают вернуть, когда починят тех, кому руки нужнее. Записано: вернут."],
  v12_blueprint: ["Перерисован лист двести третий: «Глубинник буровой, общий вид». Подпись в углу перерисована точно: «Утверждаю. Ростовцев». Чертёжник спрашивает, кто это. Ответ: тот, кто утверждает.", "Калька кончилась. Чертим на обороте старых нарядов. Мастер против. Мастер разрешил."],
  v12_smithy: ["Наковальня номер пять звенит на полтона ниже — треснула. Кузнецы горюют, как по человеку. Заменена; старую не выбросили, а поставили у двери, и на ней теперь сидят.", "Поковка дня: подкова. Коней в Цехах нет и не было. Кузнец Пахом говорит: «На счастье». Подкова прибита над воротами ряда, рогами вверх."],
  v12_hammerhall: ["Молот ударил без команды. Никто не пострадал: все стояли где положено, у стены. Молот осмотрен и исправен. Команду, видимо, он подал себе сам.", "Масло в закалочной ванне вспыхнуло. Погашено песком. Поковка вышла твёрдая, как никогда. Пометка: повторять не советую."],
  v12_rackhall: ["Сверка описи. Полок по описи — восемь тысяч. Полок на месте — больше. Откуда лишние — неизвестно. Штабелёр знает, но не говорит.", "На сорок втором стеллаже найдены заготовки с меткой, которую не узнал ни один кладовщик. Металл холодный и тихо звенит сам. Переложены повыше, подальше от рук."],
  v12_expedition: ["Отгрузка наверх: ящиков — двести, на стройку. Подъёмник ушёл и не вернулся. Ждём подъёмник. Ждём подъёмник. Ждём подъёмник.", "Тележка номер девять просит накладную на ящик с адресом «наверх». Накладная выписана. Подъёмника нет. Тележка ждёт у клети третий век."],
  v12_measure: ["Поверка эталона: линейка Глотова сверена сама с собой. Расхождений нет. Метролог пишет: «Иначе и быть не может». Мастер пишет: «Проверять всё равно».", "В метрологической чихнул посторонний. Индикаторы дрогнули на полделения. Поверка повторена. Постороннему — замечание и платок."],
  v12_testbench: ["Проба на разрыв: вал шагающего пресса. Разрушился при нагрузке втрое выше нормы. Звук разрушения записан: чистый, ровный, без хрипа. Годен.", "Проба на человеке не проводится. Пометка Мастера: «Пока». Пометка рукой поверх: «Никогда»."],
  v12_rejects: ["Брак не считается. Брак не учитывается. Брак здесь лежит. Иногда брака становится меньше, хотя никто не выносит. Не считается.", "В изоляторе брака замечен человек без жетона. Торгует. Чем — неизвестно: в табеле не значится ни он, ни его товар."],
  v12_toolcrib: ["Выдано под роспись: штамп опытный — один, резцы — двенадцать, ключ разводной — тот самый. Тот самый вернуть до конца смены, иначе премии не видать всему цеху.", "Контур на третьем щите пуст с ночи Большого простоя: напильник Глотова. Кто взял — не расписался. Контур не закрашиваем: вернут."],
  v12_grinder: ["Круг разорвало на полном ходу. Осколки — в стене, люди — за щитком. Щиток оправдал себя. Мастер: «Щиток беречь. Людей — тоже». Записано в таком порядке.", "Точильщик Ерофей точит на слух: по звону круга знает угол. Мастер проверил угломером. Угол верный. Угломер списан как лишний."],
  v12_precision: ["Деталь для эталонного калибра доведена до допуска. Мастер участка снял перчатки только после сдачи. Руки дрожали. Деталь — нет.", "Посторонний шум на участке: кто-то прошёл в сапогах. Работа остановлена на две минуты, пока не стихнет. Сапоги — в раздевалку."],
  v12_trainshop: ["Проба на разряд: ученик Ваня Глотов, напильник, кубик. Кубик ровный, звенит чисто. Разряд присвоен. Ученик плакал. Мастер записал: «от пыли».", "Стенд пробы перезапущен: отсчёт идёт, учеников нет. Стенд считает дальше. Мастер не выключает: «Вдруг придут»."],
  v12_mushfarm: ["Сбор с гряд: восемь корзин. Четвёртая гряда плодоносит через раз: на ней греются крысы. Крысы не числятся. Не согнаны: сборщица их боится.", "Полив сбился с ритма и капает вразнобой. Грибы растут кривыми. Наладчик выровнял капли по метроному. Грибы выровнялись."],
  v12_kitchen: ["Раскладка дня по Дееву: каши — черпак, хлеба — ломоть, соли — щепоть. Добавка — передовикам. Передовиков сегодня — вся смена. Добавка кончилась.", "Второй котёл кипит без огня второй век. Повара говорят: жар идёт снизу, по трубам. Пишем: кипит сам."],
  v12_packing: ["Фасовано пайков — девятьсот. Отгружено — девятьсот. Съедено, судя по возврату обёрток, — тысяча. Разницу ищем.", "Автомат фасовки работает вхолостую: заворачивает пустоту и кладёт в ящик по двадцать. Ящики пустые и аккуратные. Списывать жалко."],
  v12_cloakroom: ["Шкафчик номер один: роба на месте, каска на месте, рукавицы на месте. Хозяин не явился. Ставлю прогул. Табельщица Сухова.", "Аптечка Берг на стене: бинт — есть, жгут — есть, мазь — есть, совесть — есть. Последнее вписано не мной."],
  v12_redcorner: ["Собрание смены. Повестка: третья смена. Решили — не обсуждать. Обсуждали до утра. Протокол утерян. Протокол найден в радиоле.", "Шахматная партия на столе не доиграна с ночи Большого простоя. Фигуры не трогать: ход за чёрными, а чёрные ушли с третьей сменой."],
  v12_dorm: ["Вахта спит. Будильники заведены на гудок. Гудок дан. Вахта спит. Будильники не помогли, помог кашевар с половником.", "Капсулы сна поставлены для тех, кто стоит у вентиля по трое суток. Мастер против: «Расслабит». Капсулы стоят. Мастер в них не заглядывает."],
  v12_slagdump: ["Переведены на отвал: трое. Через полгода у одного не разжимаются руки, у другой голос стал низким, как гул снизу, у третьего кожа в окалине. Работают. Нормы дают.", "Шлак сброшен в Трещину: бадей — сорок. Звука падения нет. Трещина не наполняется. Пометка: и не наполнится."],
  v12_crackshop: ["Пол цеха ушёл в разлом за одну ночь. Станки у края остались. Лента уходит за край и возвращается пустая. Откуда возвращается — не спрашивать.", "У обрыва найден жетон третьей смены. Номер стёрт, фамилия читается наполовину: «…тов». Передан в табельную. Табельная не приняла: «Не по форме»."],
  v12_scrapsort: ["Магнитная шайба уронила груз на сортировщика. Сортировщик успел отскочить. Шайба извинилась гудком. Сортировщик — тоже, но другими словами.", "Медь — отдельно, чугун — отдельно, брак — в переплав. Звонкую руду — в отдельный ящик и с крышкой: поёт по ночам, спать мешает."],
  v12_firstlathe: ["Станок номер один смазан, проверен, работает. Номер смены, что его смазала, неизвестен: смазывают машины. Работает так же, как при первых.", "Табличка на станине: «Сделан руками». Чьими — стёрто пальцами. Кто трогает табличку, тот потом долго молчит."],
  v12_mainvalve: ["Вахта у вентиля: трое. Давление — норма. Ритм — норма. Стук снизу — не норма. Записан как «посторонний шум в трубе». В который раз — не считаю.", "Штурвал главного вентиля тёплый с той ночи. Кто приложит ладонь, говорит: будто кто-то держит его с другой стороны."],
  v12_tabelhall: ["Итог по табелю всех смен: отработали все, кроме одной. Одна — третья. Строка открыта. Строку не закрывать.", "Табельщица Сухова сверяла итог на счётах и сбилась на третьей смене. Пересчитала — сбилась снова. Счёты отложены, итог записан словами: «не все»."],
  v12_substation: ["Дежурный подстанции: напряжение в норме, гул в норме, запах озона в норме, мурашки по коже — в норме. Всё в норме, и от этого не по себе.", "Третий рубильник опущен без дежурного. Половина прессов встала. Подняли — пошли. Кто опустил — не установлено. Возможно, сквозняк. Возможно, нет."]
} });

