  v12_slagworm: { n: "Шлаковый червь", g: "m", kind: "bio", mind: 0, rank: "high", fam: "Слизни и черви",
    desc: "Червь толщиной с трубу, что живёт в остывающем шлаке у Трещины: уходит под настил, выныривает у ног и обжигает, а раны затягивает. Под полом слышно, как трещит шлак у него на пути. Холод сбивает ему жар.",
    hp: 92, dmg: 14, arm: 5, spd: 2, rng: 1, acd: 2, det: 5, beh: ["chase", "burrow", "regen"], adt: "therm", snd: "slug", sndRate: 0.65, xp: 40, res: { thermo: 0.2, cryo: 1.7 } },
